import java.util.*;

class Patient {
    final String name; final int urgency; final int arrived;
    Patient(String name, int urgency, int arrived) { this.name = name; this.urgency = urgency; this.arrived = arrived; }
    String getName() { return name; }
    int getUrgency() { return urgency; }
    int getArrived() { return arrived; }
    @Override public String toString() { return name; }
}

public class Example {
    public static void main(String[] args) {
        List<Patient> queue = new ArrayList<>(List.of(
            new Patient("Juma", 2, 900), new Patient("Amina", 5, 930), new Patient("Otieno", 5, 915)));

        queue.sort(Comparator.comparingInt(Patient::getUrgency).reversed()
                             .thenComparingInt(Patient::getArrived));
        System.out.println(queue);                  // [Otieno, Amina, Juma]

        queue.sort(Comparator.comparing(Patient::getName));
        System.out.println(queue);                  // [Amina, Juma, Otieno]

        List<String> crops = new ArrayList<>(List.of("rice", "Beans", "maize"));
        crops.sort(String.CASE_INSENSITIVE_ORDER);
        System.out.println(crops);                  // [Beans, maize, rice]
    }
}

