import java.util.*;

class Harvest implements Comparable<Harvest> {
    final String farmer;
    final String crop;
    final int kg;

    Harvest(String farmer, String crop, int kg) {
        this.farmer = farmer;
        this.crop = crop;
        this.kg = kg;
    }

    @Override
    public int compareTo(Harvest other) {
        return Integer.compare(kg, other.kg);   // not kg - other.kg
    }

    @Override
    public String toString() { return farmer + ":" + kg; }
}

public class Harvests {
    public static List<Harvest> sorted(List<Harvest> hs) {
        List<Harvest> copy = new ArrayList<>(hs);   // never change the caller's list
        Collections.sort(copy);
        return copy;
    }

    public static Harvest biggest(List<Harvest> hs) {
        return hs.isEmpty() ? null : Collections.max(hs);
    }
}

