import java.util.*;

class Score {
    private final String player;
    private final int points;
    private final int seconds;

    Score(String player, int points, int seconds) {
        this.player = player;
        this.points = points;
        this.seconds = seconds;
    }

    String getPlayer() { return player; }
    int getPoints() { return points; }
    int getSeconds() { return seconds; }
}

public class Leaderboard {
    static final Comparator<Score> RANKING =
        Comparator.comparingInt(Score::getPoints).reversed()   // most points first
                  .thenComparingInt(Score::getSeconds)         // then fastest
                  .thenComparing(Score::getPlayer);            // then A to Z

    public static List<String> rank(List<Score> scores) {
        List<Score> copy = new ArrayList<>(scores);
        copy.sort(RANKING);
        List<String> names = new ArrayList<>();
        for (Score s : copy) names.add(s.getPlayer());
        return names;
    }

    public static List<String> top(List<Score> scores, int n) {
        List<String> all = rank(scores);
        int k = Math.max(0, Math.min(n, all.size()));
        return new ArrayList<>(all.subList(0, k));
    }
}

