import java.util.*;

public class Report {
    public static List<String> byLength(List<String> names) {
        List<String> copy = new ArrayList<>(names);
        copy.sort(Comparator.comparingInt(String::length)
                            .thenComparing(String.CASE_INSENSITIVE_ORDER));
        return copy;
    }

    public static List<String> topCrops(Map<String, Integer> totals, int n) {
        List<Map.Entry<String, Integer>> es = new ArrayList<>(totals.entrySet());
        es.sort((a, b) -> {
            int byKg = Integer.compare(b.getValue(), a.getValue());   // biggest first
            return byKg != 0 ? byKg : a.getKey().compareTo(b.getKey());
        });
        List<String> out = new ArrayList<>();
        for (int i = 0; i < Math.min(n, es.size()); i++) {
            out.add(es.get(i).getKey() + " " + es.get(i).getValue());
        }
        return out;
    }
}
